#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int INF = 1e9;

int N, Q;
vector<vector<int>> adj;
vector<int> parent_node;
vector<int> depth;
vector<int> sz;
vector<int> heavy;
vector<int> head;
vector<int> pos;
int cur_pos = 0;

int up[20][100005];

struct Node {
    int d;
    int u;
};

Node min_node(const Node& a, const Node& b) {
    if (a.d < b.d) return a;
    if (b.d < a.d) return b;
    return a;
}

vector<Node> tree;

void seg_update(int node, int l, int r, int p, Node val) {
    if (l == r) {
        tree[node] = val;
        return;
    }
    int mid = (l + r) / 2;
    if (p <= mid) seg_update(2 * node, l, mid, p, val);
    else seg_update(2 * node + 1, mid + 1, r, p, val);
    tree[node] = min_node(tree[2 * node], tree[2 * node + 1]);
}

Node seg_query(int node, int l, int r, int ql, int qr) {
    if (ql > r || qr < l) return {INF, 0};
    if (ql <= l && r <= qr) return tree[node];
    int mid = (l + r) / 2;
    return min_node(seg_query(2 * node, l, mid, ql, qr),
                    seg_query(2 * node + 1, mid + 1, r, ql, qr));
}

void dfs_sz(int u, int p, int d) {
    depth[u] = d;
    parent_node[u] = p;
    up[0][u] = p;
    for (int i = 1; i < 20; ++i) {
        up[i][u] = up[i - 1][up[i - 1][u]];
    }
    sz[u] = 1;
    int max_c_sz = 0;
    for (int v : adj[u]) {
        dfs_sz(v, u, d + 1);
        sz[u] += sz[v];
        if (sz[v] > max_c_sz) {
            max_c_sz = sz[v];
            heavy[u] = v;
        }
    }
}

void dfs_hld(int u, int h) {
    head[u] = h;
    pos[u] = ++cur_pos;
    if (heavy[u] != 0) {
        dfs_hld(heavy[u], h);
    }
    for (int v : adj[u]) {
        if (v != heavy[u]) {
            dfs_hld(v, v);
        }
    }
}

int get_kth_ancestor(int u, int k) {
    for (int i = 19; i >= 0; --i) {
        if ((k >> i) & 1) {
            u = up[i][u];
        }
    }
    return u;
}

int get_highest_marked_ancestor(int u) {
    Node res = {INF, 0};
    int curr = parent_node[u];
    while (curr > 0) {
        int h = head[curr];
        Node q = seg_query(1, 1, N, pos[h], pos[curr]);
        res = min_node(res, q);
        curr = parent_node[h];
    }
    return res.u;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> N)) return 0;

    adj.assign(N + 1, vector<int>());
    parent_node.assign(N + 1, 0);
    depth.assign(N + 1, 0);
    sz.assign(N + 1, 0);
    heavy.assign(N + 1, 0);
    head.assign(N + 1, 0);
    pos.assign(N + 1, 0);

    for (int i = 2; i <= N; ++i) {
        int p;
        cin >> p;
        adj[p].push_back(i);
    }

    dfs_sz(1, 0, 1);
    dfs_hld(1, 1);

    tree.assign(4 * (N + 1), {INF, 0});

    cin >> Q;
    while (Q--) {
        int type;
        cin >> type;
        if (type == 1) {
            int v, k;
            cin >> v >> k;
            int A = get_highest_marked_ancestor(v);
            if (A != 0) {
                if (k == 1) {
                    cout << A << "\n";
                } else {
                    cout << get_kth_ancestor(A, k - 1) << "\n";
                }
            } else {
                cout << get_kth_ancestor(v, k) << "\n";
            }
        } else if (type == 2) {
            int v;
            cin >> v;
            int A = get_highest_marked_ancestor(v);
            if (A == 0) {
                seg_update(1, 1, N, pos[v], {depth[v], v});
            }
        }
    }

    return 0;
}
